1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region), preferring the postcode: the region is
7	 * looked up by postcode range first, and only when the postcode is absent or in
8	 * no known range does it fall back to a fixed city-to-region table. This returns
9	 * the same region for the known cities but disambiguates cities that share a name.
10	 *
11	 * <p>Kept as a plain static helper - rather than a method on {@link OwnerMapper} -
12	 * so MapStruct does not mistake it for an implicit String-to-String property
13	 * mapping and apply it to unrelated fields.
14	 *
15	 * <p>Public, like its sibling {@link MembershipLevel}, so the single region table
16	 * can be reused wherever an owner's region is needed rather than being
17	 * duplicated - callers outside this package derive the region through
18	 * {@link #forPostcodeAndCity(String, String)} (or {@link #forCity(String)} when
19	 * only the city is available) instead of holding their own copy of the tables.
20	 */
21	public final class OwnerLocality {
22	
23	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
24	    private static final Map<String, String> CITY_REGION = Map.of(
25	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
26	
27	    /** Region -> inclusive 4-digit postcode range {low, high}. */
28	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
29	        "NSW", new int[] {2000, 2099},
30	        "VIC", new int[] {3000, 3099},
31	        "QLD", new int[] {4000, 4099});
32	
33	    /** Region -> IANA timezone; anything not listed derives no timezone (null). */
34	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
35	        "NSW", "Australia/Sydney",
36	        "VIC", "Australia/Melbourne",
37	        "QLD", "Australia/Brisbane");
38	
39	    private OwnerLocality() {
40	    }
41	
42	    /**
43	     * Returns the canonical region for the given owner, preferring the postcode:
44	     * the region is derived from the postcode range first, falling back to the
45	     * city-to-region table only when the postcode is absent or in no known range.
46	     *
47	     * @param postcode the owner's postcode, or {@code null} when none was supplied
48	     * @param city the owner's city
49	     * @return the derived locality (region)
50	     */
51	    public static String forPostcodeAndCity(String postcode, String city) {
52	        String region = forPostcode(postcode);
53	        return region != null ? region : forCity(city);
54	    }
55	
56	    /**
57	     * Returns the owner's locality (region) as recorded in its customer code, whose
58	     * leading segment (before the first {@code '-'}) is the region derived when the
59	     * owner was created. Deriving the locality from the customer code keeps it in step
60	     * with the region-and-hash identity rather than re-deriving it independently.
61	     *
62	     * @param customerCode the owner's customer code, formatted {@code <REGION>-<HASH8>}
63	     * @return the REGION segment of the customer code, or "UNKNOWN" when it is absent
64	     */
65	    public static String forCustomerCode(String customerCode) {
66	        if (customerCode == null) {
67	            return "UNKNOWN";
68	        }
69	        int dash = customerCode.indexOf('-');
70	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
71	    }
72	
73	    /**
74	     * Returns the canonical region for the given city, or "UNKNOWN" when the city
75	     * is not in the fixed table (or is {@code null}).
76	     *
77	     * @param city the owner's city
78	     * @return the derived locality (region)
79	     */
80	    public static String forCity(String city) {
81	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
82	    }
83	
84	    /**
85	     * Returns the IANA timezone for the given region via the fixed region-to-timezone
86	     * table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD ->
87	     * Australia/Brisbane), or {@code null} when the region has no known timezone.
88	     *
89	     * @param region the owner's locality (region)
90	     * @return the IANA timezone name, or {@code null} when none is known
91	     */
92	    public static String timezoneForRegion(String region) {
93	        return region == null ? null : REGION_TIMEZONE.get(region);
94	    }
95	
96	    /**
97	     * Returns whether the given postcode falls within the postcode range of the
98	     * region derived from the city. A city whose region has no fixed range (locality
99	     * "UNKNOWN") accepts any postcode. A postcode that is absent or non-numeric is
100	     * treated as not matching a ranged region.
101	     *
102	     * <p>Callers validate a supplied postcode's four-digit shape separately; this
103	     * method only answers whether the value sits in the city's region range, so the
104	     * single region table is not duplicated at the call site.
105	     *
106	     * @param postcode the owner's postcode, or {@code null} when none was supplied
107	     * @param city the owner's city, whose region determines the acceptable range
108	     * @return {@code true} when the city's region has no fixed range, or the postcode
109	     *         lies within it
110	     */
111	    public static boolean postcodeMatchesCity(String postcode, String city) {
112	        int[] range = REGION_POSTCODES.get(forCity(city));
113	        if (range == null) {
114	            return true;
115	        }
116	        if (postcode == null) {
117	            return false;
118	        }
119	        int value;
120	        try {
121	            value = Integer.parseInt(postcode.trim());
122	        }
123	        catch (NumberFormatException e) {
124	            return false;
125	        }
126	        return value >= range[0] && value <= range[1];
127	    }
128	
129	    /**
130	     * Returns the region whose postcode range contains the given postcode, or
131	     * {@code null} when the postcode is missing, non-numeric or in no known range.
132	     */
133	    private static String forPostcode(String postcode) {
134	        if (postcode == null) {
135	            return null;
136	        }
137	        int value;
138	        try {
139	            value = Integer.parseInt(postcode.trim());
140	        }
141	        catch (NumberFormatException e) {
142	            return null;
143	        }
144	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
145	            int[] range = entry.getValue();
146	            if (value >= range[0] && value <= range[1]) {
147	                return entry.getKey();
148	            }
149	        }
150	        return null;
151	    }
152	
153	}
