51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.util.StringUtils;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
73	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
74	     * addresses are lower-cased before being stored.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** An owner's postcode, when supplied, must be exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
84	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /**
90	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
91	     * named logger keeps them addressable independently of the class's diagnostic logging.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Maximum number of owners a single city may contain. A create that would take the owner's city
97	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
98	     */
99	    private static final int CITY_OWNER_LIMIT = 50;
100	
101	    /**
102	     * Maximum number of owners that may be registered on a single day. A create that would take the
103	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
104	     * have already been created that day - is rejected with a 429.
105	     */
106	    private static final int DAILY_OWNER_LIMIT = 100;
107	
108	    /**
109	     * Number of owners that must already have been created for a given day before the create
110	     * response flags a bulk sign-up. When more than this many owners already share a
111	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    private final ClinicService clinicService;
116	
117	    private final OwnerMapper ownerMapper;
118	
119	    private final PetMapper petMapper;
120	
121	    private final VisitMapper visitMapper;
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper) {
127	        this.clinicService = clinicService;
128	        this.ownerMapper = ownerMapper;
129	        this.petMapper = petMapper;
130	        this.visitMapper = visitMapper;
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
157	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
158	    }
159	
160	    /**
161	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
162	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
163	     * owner sign-ups.
164	     *
165	     * @param registrationDate the day to inspect, or {@code null}
166	     * @return {@code true} when more than the threshold of owners are registered on that day
167	     */
168	    private boolean isBulkSignupDay(LocalDate registrationDate) {
169	        return registrationDate != null
170	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
176	        resolveAddressFields(ownerFieldsDto);
177	        validateRequiredFields(ownerFieldsDto);
178	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
182	        owner.setEmail(normalizeEmail(owner.getEmail()));
183	        validateRegistrationDate(owner.getRegistrationDate());
184	        if (owner.getRegistrationDate() == null) {
185	            owner.setRegistrationDate(LocalDate.now());
186	        }
187	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
188	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
189	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
190	        owner.setIdentityKey(buildIdentityKey(owner));
191	        if (!sharesHousehold) {
192	            rejectHouseholdDuplicate(owner.getHouseholdId());
193	        }
194	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
195	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
196	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
197	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
198	            throw new OwnerCityFullException(owner.getCity());
199	        }
200	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
201	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
202	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
203	        }
204	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
205	        owner.setCustomerCode(buildCustomerCode(owner));
206	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
207	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
208	        this.clinicService.saveOwner(owner);
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
211	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
212	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
213	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
214	        headers.setLocation(UriComponentsBuilder.newInstance()
215	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
216	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
217	    }
218	
219	    /**
220	     * Canonicalizes the submitted address fields into the form that is validated, stored and
221	     * returned, before any required-field check or mapping runs. This is the single place a create
222	     * request's address input is resolved: the submitted {@code address} is replaced in place with
223	     * its {@link AddressNormalizer#normalize normalized} value, so everything downstream - the
224	     * required-field check, the mapping onto {@link Owner} and the response - sees the canonical
225	     * address rather than the raw input. A value that is blank only after normalization is left
226	     * blank here and rejected later by {@link #validateRequiredFields}.
227	     *
228	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
229	     */
230	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
231	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
232	    }
233	
234	    /**
235	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
236	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
237	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
238	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
239	     * after normalization is still rejected.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields
242	     */
243	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
244	        List<String> missingFields = new ArrayList<>();
245	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
246	            missingFields.add("firstName");
247	        }
248	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
249	            missingFields.add("lastName");
250	        }
251	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
252	            missingFields.add("address");
253	        }
254	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
255	            missingFields.add("city");
256	        }
257	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
258	            missingFields.add("telephone");
259	        }
260	        if (!missingFields.isEmpty()) {
261	            throw new MissingOwnerFieldsException(missingFields);
262	        }
263	    }
264	
265	    /**
266	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
267	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
268	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
269	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
270	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
271	     * whose {@code errors} array lists {@code postcode}.
272	     *
273	     * @param postcode the submitted postcode, or {@code null} when none was supplied
274	     * @param city the owner's city, whose region determines the acceptable postcode range
275	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
276	     */
277	    private void validatePostcode(String postcode, String city) {
278	        if (!StringUtils.hasText(postcode)) {
279	            return;
280	        }
281	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
282	            throw new InvalidOwnerFieldsException(List.of("postcode"));
283	        }
284	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
285	            throw new InvalidOwnerFieldsException(List.of("postcode"));
286	        }
287	    }
288	
289	    /**
290	     * Validates an owner's optional registration date. Registration date is optional, so a missing
291	     * value is accepted (the create later defaults it to the server date). When a value is supplied
292	     * it may not lie in the future: a date later than the server's current date is rejected with a
293	     * 400 whose {@code errors} array lists {@code registrationDate}.
294	     *
295	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
296	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
297	     */
298	    private void validateRegistrationDate(LocalDate registrationDate) {
299	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
300	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
301	        }
302	    }
303	
304	    /**
305	     * Rejects a submitted owner that would join a household which already has a member. Because the
306	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
307	     * existing owner sharing that id is the same household, so a second such owner is reported to the
308	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
309	     * {@code sharesHousehold}, in which case this check is not performed.
310	     *
311	     * @param householdId the derived household identifier of the owner about to be created
312	     */
313	    private void rejectHouseholdDuplicate(String householdId) {
314	        boolean duplicate = this.clinicService.findAllOwners().stream()
315	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
316	        if (duplicate) {
317	            throw new DuplicateOwnerIdentityException(householdId);
318	        }
319	    }
320	
321	    /**
322	     * Derives the owner's {@code identityKey}, formatted
323	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
324	     * and email have already been normalized. The household segment always carries the owner's
325	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
326	     * the same household automatically.
327	     *
328	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
329	     * @return the derived identity key
330	     */
331	    private String buildIdentityKey(Owner owner) {
332	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
333	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
334	    }
335	
336	    /**
337	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
338	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
339	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
340	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
341	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
342	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
343	     * postcode was supplied, since both owners must share one; when several existing owners match, the
344	     * earliest (lowest id) is used.
345	     *
346	     * @param owner the normalized owner about to be created, with its telephone already normalized
347	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
348	     */
349	    private Integer findPossibleDuplicate(Owner owner) {
350	        if (!StringUtils.hasText(owner.getPostcode())) {
351	            return null;
352	        }
353	        return this.clinicService.findAllOwners().stream()
354	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
355	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
356	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
357	            .map(Owner::getId)
358	            .filter(id -> id != null)
359	            .min(Integer::compareTo)
360	            .orElse(null);
361	    }
362	
363	    /**
364	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
365	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
366	     * address; the accepted value is lower-cased before it is stored and returned.
367	     *
368	     * @param email the raw email value submitted by the client, or {@code null}
369	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
370	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
371	     */
372	    private String normalizeEmail(String email) {
373	        if (!StringUtils.hasText(email)) {
374	            return email;
375	        }
376	        if (!EMAIL_PATTERN.matcher(email).matches()) {
377	            throw new InvalidOwnerFieldsException(List.of("email"));
378	        }
379	        String normalized = email.toLowerCase();
380	        String domain = normalized.substring(normalized.indexOf('@') + 1);
381	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
382	            throw new InvalidOwnerFieldsException(List.of("email"));
383	        }
384	        return normalized;
385	    }
386	
387	    /**
388	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
389	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
390	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
391	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
392	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
393	     *
394	     * @param owner the normalized owner about to be created
395	     * @return the assigned, de-duplicated customer code
396	     */
397	    private String buildCustomerCode(Owner owner) {
398	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
399	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
400	        return deduplicateCustomerCode(code);
401	    }
402	
403	    /**
404	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
405	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
406	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
407	     *
408	     * @param code the composed customer code, before de-duplication
409	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
410	     */
411	    private String deduplicateCustomerCode(String code) {
412	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
413	            .map(Owner::getCustomerCode)
414	            .filter(existing -> existing != null)
415	            .collect(Collectors.toSet());
416	        if (!existingCodes.contains(code)) {
417	            return code;
418	        }
419	        int suffix = 2;
420	        while (existingCodes.contains(code + "-" + suffix)) {
421	            suffix++;
422	        }
423	        return code + "-" + suffix;
424	    }
425	
426	    /**
427	     * Counts how many owners already exist that share the supplied first and last name, compared
428	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
429	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
430	     *
431	     * @param firstName the submitted owner's first name
432	     * @param lastName the submitted owner's last name
433	     * @return the number of existing owners with the same first and last name, ignoring case
434	     */
435	    private int countNamesakes(String firstName, String lastName) {
436	        return (int) this.clinicService.findAllOwners().stream()
437	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
438	                && lastName.equalsIgnoreCase(existing.getLastName()))
439	            .count();
440	    }
441	
442	    /**
443	     * Counts how many existing owners already belong to the supplied household, identified by its
444	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
445	     * owner is added (this count plus one).
446	     *
447	     * @param householdId the normalized household identifier of the owner being created
448	     * @return the number of existing owners already sharing that {@code householdId}
449	     */
450	    private int countHouseholdMembers(String householdId) {
451	        return (int) this.clinicService.findAllOwners().stream()
452	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
453	            .count();
454	    }
455	
456	    /**
457	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
458	     * enforce the per-city capacity limit when a new owner is created.
459	     *
460	     * @param city the submitted owner's city
461	     * @return the number of existing owners in that city, ignoring case
462	     */
463	    private long countOwnersInCity(String city) {
464	        return this.clinicService.findAllOwners().stream()
465	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
466	            .count();
467	    }
468	
469	    /**
470	     * Counts how many owners have already been created on the supplied registration date. Used to
471	     * enforce the per-day capacity limit when a new owner is created.
472	     *
473	     * @param registrationDate the registration date of the owner being created
474	     * @return the number of existing owners already registered on that date
475	     */
476	    /**
477	     * Rolls a registration date forward to a business day. A registration date must fall on a
478	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
479	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
480	     * from the registration date (such as the membership number's year segment) and the daily
481	     * create-limit therefore use the adjusted date.
482	     *
483	     * @param date the effective registration date, whether supplied or defaulted to the server date
484	     * @return the same date when it is a weekday, otherwise the next Monday
485	     */
486	    private LocalDate toBusinessDay(LocalDate date) {
487	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
488	            date = date.plusDays(1);
489	        }
490	        return date;
491	    }
492	
493	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
494	        return this.clinicService.findAllOwners().stream()
495	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
496	            .count();
497	    }
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Override
501	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
502	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
503	        if (currentOwner == null) {
504	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
505	        }
506	        currentOwner.setAddress(ownerFieldsDto.getAddress());
507	        currentOwner.setCity(ownerFieldsDto.getCity());
508	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
509	        currentOwner.setLastName(ownerFieldsDto.getLastName());
510	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
511	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
512	        this.clinicService.saveOwner(currentOwner);
513	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
514	    }
515	
516	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
517	    @Transactional
518	    @Override
519	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
520	        Owner owner = this.clinicService.findOwnerById(ownerId);
521	        if (owner == null) {
522	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
523	        }
524	        this.clinicService.deleteOwner(owner);
525	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
526	    }
527	
528	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
529	    @Override
530	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
531	        Owner owner = this.clinicService.findOwnerById(ownerId);
532	        if (owner == null) {
533	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
534	        }
535	        HttpHeaders headers = new HttpHeaders();
536	        Pet pet = petMapper.toPet(petFieldsDto);
537	        owner.setId(ownerId);
538	        pet.setOwner(owner);
539	        pet.getType().setName(null);
540	        this.clinicService.savePet(pet);
541	        PetDto petDto = petMapper.toPetDto(pet);
542	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
543	            .buildAndExpand(pet.getId()).toUri());
544	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
545	    }
546	
547	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
548	    @Override
549	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
550	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
551	        if (currentOwner != null) {
552	            Pet currentPet = this.clinicService.findPetById(petId);
553	            if (currentPet != null) {
554	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
555	                currentPet.setName(petFieldsDto.getName());
556	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
557	                this.clinicService.savePet(currentPet);
558	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
559	            }
560	        }
561	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
562	    }
563	
564	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
565	    @Override
566	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
567	        HttpHeaders headers = new HttpHeaders();
568	        Visit visit = visitMapper.toVisit(visitFieldsDto);
569	        Pet pet = new Pet();
570	        pet.setId(petId);
571	        visit.setPet(pet);
572	        this.clinicService.saveVisit(visit);
573	        VisitDto visitDto = visitMapper.toVisitDto(visit);
574	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
575	            .buildAndExpand(visit.getId()).toUri());
576	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
577	    }
578	
579	
580	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
581	    @Override
582	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
583	        Owner owner = this.clinicService.findOwnerById(ownerId);
584	        if (owner != null) {
585	            Pet pet = owner.getPet(petId);
586	            if (pet != null) {
587	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
588	            }
589	        }
590	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
591	    }
592	}
